-- Daily challenges for 2026-11-13: two new themes, 365 to-dos each (added on 2026-11-21 to fill a missed day).
-- Generated by tools/challenges_sql.py watching-the-birds-around-you recharging-after-busy-social-times. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('watching-the-birds-around-you', 'Watching the Birds Around You', 'For anyone who could use a few calm minutes outside their own head. Each day is one small way to notice the birds near your home, work or commute, from their songs and colors to their habits through the seasons.', 'Mindfulness', 365, array['Mindfulness', 'Grounding']::text[], 1, '2026-11-13T17:00:00+00:00'::timestamptz),
  ('recharging-after-busy-social-times', 'Recharging After Busy Social Times', 'For anyone who enjoys people but feels drained after a full day of them. Each day is one small way to plan, protect and enjoy quiet time to recover after gatherings, workdays, trips and holidays, without feeling guilty for needing it.', 'Rest', 365, array['Self-Care', 'Social Anxiety']::text[], 1, '2026-11-13T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('watching-the-birds-around-you', 'recharging-after-busy-social-times');

